from app.registry import Message, MessageCatalog, NodeSpec, Port, param, register

# AI node: executor uses build_code path via is_ai + empty execute
# Code is generated by AI and run in sandbox (code_profile=ai)

SPEC = register(
    NodeSpec(
        type="ai_clean",
        category="clean",
        label="AI 清洗",
        label_en="AI Clean",
        description="用自然语言描述清洗意图，由 AI 生成 pandas 代码",
        keywords=("清洗", "缺失值", "去重", "clean", "dedupe"),
        icon="clean",
        priority=100,
        inputs=[Port("table_in", "table", "表格")],
        outputs=[Port("table_out", "table", "表格", default=True)],
        params_schema=[
            param("columns", "columns", False, "关注字段"),
            param("intent", "textarea", True, "处理意图"),
            param("model", "model", False, "AI 模型"),
        ],
        is_ai=True,
        code_profile="ai",
        messages=MessageCatalog(
            error={
                "empty_result": Message("empty_result", "清洗后结果为空表", "放宽清洗条件"),
            },
        ),
    )
)
